const inbound = $('2. Fetch Daily Inbound Volume Postgres').first().json;
const ticketStats = $input.first().json;

const totalEmailsToday = Number(inbound.total_emails_today) || 0;
const spamBlockedToday = Number(inbound.spam_blocked_today) || 0;

const totalTickets = Number(ticketStats.total_tickets) || 0;
const resolvedTickets = Number(ticketStats.resolved_tickets) || 0;
const p1CountToday = Number(ticketStats.p1_count) || 0;
const pendingTickets = Number(ticketStats.pending_tickets) || 0;
const slaComplianceRate = Number(ticketStats.sla_compliance_rate) || 100.0;

// Tính toán trung bình P1 trong 7 ngày qua (baseline)
const p1Past7Days = Number(ticketStats.p1_past_7_days) || 0;
const baselineDailyP1 = Math.max(1.0, p1Past7Days / 7);

// Tính tỷ lệ tăng trưởng P1 so với mức trung bình
const increasePercent = Math.round(((p1CountToday - baselineDailyP1) / baselineDailyP1) * 100);

// Đánh cờ is_spike_detected = true nếu phát sinh lỗi P1 vượt quá 20%
const isSpikeDetected = (p1CountToday > 0 && increasePercent > 20);

const summaryDate = new Date().toISOString().slice(0, 10);

return [{
  json: {
    summary_date: summaryDate,
    total_emails_today: totalEmailsToday,
    spam_blocked_today: spamBlockedToday,
    total_tickets: totalTickets,
    resolved_tickets: resolvedTickets,
    pending_tickets: pendingTickets,
    p1_count: p1CountToday,
    baseline_daily_p1: Number(baselineDailyP1.toFixed(2)),
    increase_percent: increasePercent,
    is_spike_detected: isSpikeDetected,
    sla_compliance_rate: slaComplianceRate
  }
}];

const metrics = $('4. Detect Incident Spike Code').first().json;
const aiResp = $input.first().json;

let aiData = {};
let rawText = '';
if (aiResp && aiResp.output) {
  rawText = String(aiResp.output);
} else if (aiResp && aiResp.candidates && aiResp.candidates[0]?.content?.parts?.[0]?.text) {
  rawText = aiResp.candidates[0].content.parts[0].text;
} else if (aiResp && aiResp.text) {
  rawText = String(aiResp.text);
}

if (rawText) {
  try {
    const clean = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
    aiData = JSON.parse(clean);
  } catch(e) {}
}

let summaryText = aiData.executive_summary;
if (!summaryText || summaryText.includes('{{') || summaryText.includes('$(')) {
  summaryText = metrics.is_spike_detected 
    ? `Hệ thống ghi nhận sự gia tăng đột biến lỗi mức độ P1 (${metrics.p1_count} sự cố, tăng ${metrics.increase_percent}% so với ngưỡng trung bình). Yêu cầu đội ngũ trực nhật kỹ thuật khẩn trương kiểm tra và xử lý dứt điểm.`
    : `Hệ thống vận hành ổn định trong ngày ${metrics.summary_date}. Tổng số ${metrics.total_emails_today} email đã tiếp nhận, ${metrics.total_tickets} vé sự cố được xử lý với tỷ lệ tuân thủ SLA đạt ${metrics.sla_compliance_rate}%.`;
}

const rootCauses = (Array.isArray(aiData.key_insights) && aiData.key_insights.length > 0 && !aiData.key_insights.some(x => String(x).includes('{{'))) 
  ? aiData.key_insights 
  : [
      'Lưu lượng truy cập cổng API duy trì ở mức bình thường, không ghi nhận nghẽn cổ chai.',
      'Toàn bộ dịch vụ xác thực và định tuyến thư điện tử vận hành an toàn.'
    ];

const recommendations = (Array.isArray(aiData.action_recommendations) && aiData.action_recommendations.length > 0 && !aiData.action_recommendations.some(x => String(x).includes('{{'))) 
  ? aiData.action_recommendations 
  : [
      'Duy trì cơ chế giám sát 24/7 và kiểm tra định kỳ hàng đợi thư gửi đi.',
      'Tiếp tục thực hiện quy trình SOP tiếp nhận và điều phối vé theo cam kết SLA.'
    ];

// Format HTML Digest chuyên nghiệp cho Ban Giám Đốc
const htmlDigest = `<!DOCTYPE html>
<html lang="vi">
<head><meta charset="UTF-8"><title>Báo Cáo Điều Hành Doanh Nghiệp</title></head>
<body style="margin:0;padding:0;background-color:#0b0f19;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#1e293b;">
  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="padding:40px 15px;">
    <tr><td align="center">
      <table role="presentation" width="680" cellspacing="0" cellpadding="0" style="background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 25px 50px rgba(0,0,0,0.4);max-width:680px;width:100%;">
        <tr>
          <td style="background:linear-gradient(135deg, #1e1b4b 0%, #4338ca 100%);padding:32px 40px;color:#ffffff;">
            <div style="font-size:11px;font-weight:bold;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:6px;opacity:0.9;">EXECUTIVE INTELLIGENCE &bull; BAN LÃNH ĐẠO</div>
            <h1 style="margin:0;font-size:22px;font-weight:bold;">BÁO CÁO TỔNG KẾT VẬN HÀNH HẰNG NGÀY</h1>
            <div style="margin-top:8px;font-size:13px;opacity:0.9;">Ngày báo cáo: <strong>${metrics.summary_date}</strong> &bull; Tổng hợp tự động bởi AI Agent 5</div>
          </td>
        </tr>
        ${metrics.is_spike_detected ? `
        <tr>
          <td style="background:#fef2f2;border-bottom:2px solid #ef4444;padding:16px 40px;">
            <strong style="color:#b91c1c;font-size:14px;">🚨 CẢNH BÁO ĐỘT BIẾN SỰ CỐ KHẨN CẤP:</strong>
            <span style="color:#991b1b;font-size:13px;"> Tỷ lệ lỗi P1 tăng ${metrics.increase_percent}% so với mức trung bình 7 ngày qua!</span>
          </td>
        </tr>` : ''}
        <tr>
          <td style="padding:32px 40px;">
            <table width="100%" cellspacing="0" cellpadding="0" style="margin-bottom:28px;">
              <tr>
                <td width="24%" style="background:#f8fafc;padding:16px;border-radius:10px;text-align:center;border:1px solid #e2e8f0;">
                  <div style="font-size:11px;color:#64748b;font-weight:bold;text-transform:uppercase;">Email Tiếp Nhận</div>
                  <div style="font-size:24px;font-weight:bold;color:#0f172a;margin-top:4px;">${metrics.total_emails_today}</div>
                </td>
                <td width="4%"></td>
                <td width="24%" style="background:#f8fafc;padding:16px;border-radius:10px;text-align:center;border:1px solid #e2e8f0;">
                  <div style="font-size:11px;color:#64748b;font-weight:bold;text-transform:uppercase;">Vé Sự Cố</div>
                  <div style="font-size:24px;font-weight:bold;color:#4f46e5;margin-top:4px;">${metrics.total_tickets}</div>
                </td>
                <td width="4%"></td>
                <td width="24%" style="background:#f8fafc;padding:16px;border-radius:10px;text-align:center;border:1px solid #e2e8f0;">
                  <div style="font-size:11px;color:#64748b;font-weight:bold;text-transform:uppercase;">Tuân Thủ SLA</div>
                  <div style="font-size:24px;font-weight:bold;color:#059669;margin-top:4px;">${metrics.sla_compliance_rate}%</div>
                </td>
                <td width="4%"></td>
                <td width="24%" style="background:#f8fafc;padding:16px;border-radius:10px;text-align:center;border:1px solid #e2e8f0;">
                  <div style="font-size:11px;color:#64748b;font-weight:bold;text-transform:uppercase;">Sự Cố P1</div>
                  <div style="font-size:24px;font-weight:bold;color:${metrics.p1_count > 0 ? '#dc2626' : '#059669'};margin-top:4px;">${metrics.p1_count}</div>
                </td>
              </tr>
            </table>
            <h3 style="font-size:15px;color:#0f172a;margin:0 0 10px 0;">📌 Tóm Tắt Tình Hình Điều Hành:</h3>
            <div style="font-size:14px;line-height:1.7;color:#334155;background:#f8fafc;padding:18px;border-radius:10px;border-left:4px solid #4f46e5;">
              ${summaryText}
            </div>
            <h3 style="font-size:15px;color:#0f172a;margin:24px 0 10px 0;">🔍 Phân Tích Thông Tin & Khuyến Nghị:</h3>
            <ul style="font-size:13px;color:#475569;line-height:1.6;padding-left:20px;margin:0;">
              ${rootCauses.map(r => `<li><strong>Thông tin:</strong> ${r}</li>`).join('')}
              ${recommendations.map(r => `<li><strong>Hành động:</strong> ${r}</li>`).join('')}
            </ul>
            <div style="margin-top:32px;text-align:center;">
              <a href="http://localhost:3000/analytics" style="background:#4338ca;color:#ffffff;text-decoration:none;padding:12px 28px;border-radius:8px;font-weight:bold;font-size:13px;display:inline-block;">Xem Bảng Điều Khiển Executive Analytics</a>
            </div>
          </td>
        </tr>
      </table>
    </td></tr>
  </table>
</body>
</html>`;

const emergencyAlertHtml = `<!DOCTYPE html>
<html lang="vi">
<head><meta charset="UTF-8"><title>Cảnh Báo Đỏ Khẩn Cấp CEO</title></head>
<body style="background-color:#450a0a;font-family:sans-serif;color:#ffffff;padding:30px;">
  <div style="max-width:600px;margin:0 auto;background:#18181b;padding:30px;border-radius:12px;border:2px solid #ef4444;">
    <h1 style="color:#ef4444;margin:0 0 10px 0;font-size:20px;">🚨 [CẢNH BÁO ĐỎ KHẨN CẤP] ĐỘT BIẾN SỰ CỐ P1 DOANH NGHIỆP</h1>
    <p style="color:#fecaca;">Kính gửi Tổng Giám Đốc và Hội đồng Quản trị,</p>
    <p style="font-size:14px;line-height:1.6;color:#e4e4e7;">
      Hệ thống AI Điều hành vừa kích hoạt cơ chế báo động cấp bách do số lượng sự cố nghiêm trọng (P1) ngày hôm nay (${metrics.summary_date}) đã tăng <strong>${metrics.increase_percent}%</strong> so với trung bình 7 ngày qua.
    </p>
    <table width="100%" style="background:#27272a;padding:15px;border-radius:8px;font-size:13px;margin:20px 0;">
      <tr><td>Số sự cố P1 hôm nay:</td><td><strong style="color:#ef4444;">${metrics.p1_count}</strong></td></tr>
      <tr><td>Tỷ lệ vượt ngưỡng:</td><td><strong style="color:#f59e0b;">+${metrics.increase_percent}%</strong></td></tr>
      <tr><td>SLA hiện thời:</td><td><strong>${metrics.sla_compliance_rate}%</strong></td></tr>
    </table>
    <a href="http://localhost:3000/analytics" style="display:inline-block;background:#dc2626;color:#ffffff;padding:12px 24px;border-radius:6px;text-decoration:none;font-weight:bold;font-size:13px;">Vào Trung Tâm Điều Hành Khẩn Cấp</a>
  </div>
</body>
</html>`;

return [{
  json: {
    ...metrics,
    executive_summary: summaryText,
    html_digest: htmlDigest,
    emergency_alert_html: emergencyAlertHtml,
    recipient_emails: 'tranngo170770@gmail.com'
  }
}];

